"""Desktop pane allocation and shared row grammar; isolated browser profile/data."""
import json


def run_sidebar_refinement_checks(*,cdp,e,check,wait_for,add,shot):
    q=json.dumps
    frame='new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)))'
    check(e('!tasksView.activeSection.collapsed&&tasksView.completedSection.collapsed'),'Active defaults expanded and Completed defaults collapsed')
    root=add('Travel')
    child=add('Europe',root)
    for i in range(26):add('Destination '+str(i),root)
    e(f'createChildEntry({q(root)},true);fields[0].value="Show with a long checklist name that truncates gracefully";document.getElementById("task-list-tasks").value=Array.from({{length:28}},(_,i)=>"Task "+i).join(String.fromCharCode(10));form.requestSubmit();applicationCommandTail')
    assert e('!dialog.open'), e('formError.textContent')
    wait_for('!dialog.open&&!formSaveBusy')
    task_list=e('selectedNode.dataset.entryId')
    task=e(f'galaxyModel.childrenOf(entries,{q(task_list)})[0].id')
    e(f'physics.pause();camera.stopAnimation();hierarchySidebar.expanded.add({q(root)});hierarchySidebar.render();hierarchySidebar.setCollapsed(false);tasksView.rows.get({q(task_list)}).expand.click()')
    e(frame)
    def rect(selector):
        e(f'(()=>{{if(!hierarchySidebar.narrow)return;const root=document.querySelector({q(selector)})?.closest("#universe-section,#tasks-section,#constellations-section");const section=mobileSidebarSections.sections.find(s=>s.root===root);if(section)mobileSidebarSections.select(section)}})()');e(frame)
        return e(f'(()=>{{const r=document.querySelector({q(selector)}).getBoundingClientRect();return {{x:r.x,y:r.y,width:r.width,height:r.height,bottom:r.bottom}}}})()')
    def drag(dy):
        r=rect('#sidebar-pane-splitter');x=r['x']+r['width']/2;y=r['y']+r['height']/2
        cdp.call('Input.dispatchMouseEvent',type='mouseMoved',x=x,y=y)
        cdp.call('Input.dispatchMouseEvent',type='mousePressed',button='left',buttons=1,clickCount=1,x=x,y=y)
        e(frame)
        cdp.call('Input.dispatchMouseEvent',type='mouseMoved',button='left',buttons=1,x=x,y=y+dy)
        cdp.call('Input.dispatchMouseEvent',type='mouseReleased',button='left',clickCount=1,x=x,y=y+dy)
        e(frame)
    def reload():
        cdp.call('Page.reload',ignoreCache=True)
        wait_for('document.readyState==="complete"&&typeof sidebarPaneSplit!=="undefined"&&entries.size>0')
        wait_for('physics.settled',timeout=25);e('applicationCommandTail');e(frame)
    parent=f'.hierarchy-row[data-entry-id="{root}"]'
    universe_child=f'.hierarchy-row[data-entry-id="{child}"]'
    listrow=f'#tasks-view [data-task-list-id="{task_list}"] .tasks-list-row'
    taskrow=f'#tasks-view [data-task-id="{task}"]'
    check(e('!sidebarPaneSplit.handle.hidden&&sidebarPaneSplit.enabled'),'desktop exposes focusable pane separator')
    check(e('sidebarPaneSplit.handle.role==="separator"&&sidebarPaneSplit.handle.tabIndex===0&&sidebarPaneSplit.handle.hasAttribute("aria-valuenow")'),'splitter has adjustable separator semantics')
    check(rect('#universe-section')['height']>rect('#sidebar-secondary-views')['height'],'default layout favors Universe')
    check(e('["universe-heading","tasks-heading","constellations-heading"].every(id=>{const s=getComputedStyle(document.getElementById(id));return s.fontSize==="10px"&&s.textTransform==="uppercase"})'),'all three headings share typography')
    for a,b,label in [(parent,listrow,'parent'),(universe_child,taskrow,'child')]:
        check(e(f'(()=>{{const a=getComputedStyle(document.querySelector({q(a)})),b=getComputedStyle(document.querySelector({q(b)}));return a.fontSize===b.fontSize&&a.lineHeight===b.lineHeight&&a.height===b.height}})()'),label+' rows share type, line height and row height')
        check(abs(rect(b+(' .tasks-list-name' if label=='parent' else ' .tasks-task-name'))['x']-rect(a+' .tree-name')['x']-14)<1,label+' names follow the shared Universe staircase after the subgroup')
    check(abs(rect(taskrow+' .task-view-check')['x']-rect(universe_child+' .tree-disclosure')['x']-14)<1,'task checkbox occupies its hierarchy disclosure gutter')
    e('constellationWorkspace.openName();document.getElementById("constellation-name").value="Favorites";constellationWorkspace.saveName()');e(frame)
    e('if(constellationWorkspace.collapsed)constellationWorkspace.sectionToggle.click()');e(frame)
    def hierarchy_alignment(label,step):
        positions=e('(()=>{const x=s=>document.querySelector(s).getBoundingClientRect().x;return {roots:["#universe-home","#tasks-toggle span","#constellations-toggle span"].map(s=>x(s)+(s==="#universe-home"?parseFloat(getComputedStyle(document.querySelector(s)).paddingLeft):0)),chevrons:["#universe-toggle svg","#tasks-toggle svg","#constellations-toggle svg"].map(s=>{const r=document.querySelector(s).getBoundingClientRect();return r.x+r.width/2})}})()')
        check(max(positions['roots'])-min(positions['roots'])<1,'root section text shares one left edge: '+label)
        check(e('(()=>{const values=["#universe-home","#tasks-toggle span","#constellations-toggle span"].map(s=>{const c=getComputedStyle(document.querySelector(s));return [c.fontSize,c.fontWeight,c.textTransform,c.color].join("|")});return new Set(values).size===1})()'),'root headings share typography and color: '+label)
        check(max(positions['chevrons'])-min(positions['chevrons'])<1,'root section disclosures share one gutter: '+label+' '+str(positions))
        check(abs(rect(parent+' .tree-name')['x']-positions['roots'][0]-step)<1,'Universe root CB is one shared step beneath its section: '+label)
        group_x=rect('#tasks-active-toggle span')['x'];list_x=rect(listrow+' .tasks-list-name')['x'];task_x=rect(taskrow+' .tasks-task-name')['x']
        check(abs(group_x-positions['roots'][1]-step)<1,'Active subgroup is one shared step beneath Tasks: '+label)
        check(abs(group_x-rect('#tasks-completed-toggle span')['x'])<1,'Active and Completed are peer groups: '+label)
        check(abs(list_x-group_x-step)<1 and abs(task_x-list_x-step)<1,'Task Lists and tasks staircase by one shared step each: '+label)
        check(abs(rect('.constellation-name')['x']-positions['roots'][2]-step)<1,'Constellation item is one shared step beneath its section: '+label)
    hierarchy_alignment('desktop',14)
    label_x=rect(taskrow+' .tasks-task-name')['x']
    e(f'changeTask({q(task)},"completed",true)');wait_for('camera.frame===null')
    check(rect(taskrow+' .tasks-task-name')['x']==label_x,'completion does not shift task label')
    check(e(f'entries.get({q(task)}).completed&&document.querySelector({q(taskrow+" .task-view-check")}).ariaChecked==="true"'),'sidebar completion stays functional')
    name=rect(listrow+' .tasks-list-name');summary=rect(listrow+' .tasks-summary')
    check(abs(name['y']+name['height']/2-summary['y']-summary['height']/2)<1,'muted progress count vertically centers on list name')
    e(f'createChildEntry({q(root)},true);fields[0].value="Finished list";document.getElementById("task-list-tasks").value="Done task";form.requestSubmit();applicationCommandTail')
    finished=e('selectedNode.dataset.entryId')
    e(f'changeTask(galaxyModel.childrenOf(entries,{q(finished)})[0].id,"completed",true)');wait_for('camera.frame===null')
    e('tasksView.completedSection.setCollapsed(true)');e(frame)
    check(e('getComputedStyle(tasksView.completedToggle).fontSize==="9px"&&getComputedStyle(tasksView.completedToggle).textTransform==="uppercase"'),'Completed uses normal subgroup typography')
    check(abs(rect('#tasks-completed-toggle svg')['x']-rect('#tasks-active-toggle svg')['x'])<1,'Active and Completed use peer disclosure indentation')
    e('tasksView.completedToggle.click()');e(frame)
    check(e(f'!tasksView.completed.hidden&&tasksView.rows.get({q(finished)}).item.parentElement===tasksView.completed'),'Completed still expands to canonical finished lists')
    finished_row=f'#tasks-view [data-task-list-id="{finished}"]'
    check(abs(rect(finished_row+' .tasks-list-name')['x']-rect(listrow+' .tasks-list-name')['x'])<1,'Active and Completed checklist names share the same hierarchy depth')
    e(f'tasksView.rows.get({q(finished)}).expand.click()');e(frame)
    check(abs(rect(finished_row+' .tasks-task-name')['x']-rect(taskrow+' .tasks-task-name')['x'])<1,'Active and Completed task names share the same hierarchy depth')
    e('tasksView.completedToggle.click()')
    width=rect('#hierarchy-sidebar')['width'];top=rect('#universe-section')['height']
    drag(-120)
    check(rect('#universe-section')['height']<top-80,'dragging up gives space to secondary pane')
    top=rect('#universe-section')['height'];drag(90)
    check(rect('#universe-section')['height']>top+60,'dragging down gives space to Universe')
    check(rect('#hierarchy-sidebar')['width']==width,'vertical splitter preserves sidebar width')
    drag(-2000)
    check(e('Math.abs(sidebarPaneSplit.current.top-sidebarPaneSplit.current.min)<1'),'drag clamps to Universe minimum')
    drag(2000)
    check(e('Math.abs(sidebarPaneSplit.current.top-sidebarPaneSplit.current.max)<1'),'drag clamps to secondary minimum')
    e('sidebarPaneSplit.handle.focus()');top=rect('#universe-section')['height']
    cdp.call('Input.dispatchKeyEvent',type='keyDown',key='ArrowUp',code='ArrowUp',windowsVirtualKeyCode=38)
    cdp.call('Input.dispatchKeyEvent',type='keyUp',key='ArrowUp',code='ArrowUp',windowsVirtualKeyCode=38);e(frame)
    check(abs(rect('#universe-section')['height']-top+16)<1,'keyboard Arrow Up adjusts pane height by 16px')
    e('tasksView.activeToggle.click();tasksView.completedToggle.click()');e(frame)
    check(e('tasksView.active.hidden&&!tasksView.completed.hidden'),'both groups independently follow manual disclosure')
    ratio=e('persistence.preferences.load().sidebarPaneRatio');reload()
    check(e(f'sidebarPaneSplit.ratio==={ratio}'),'desktop split survives reload in navigation preferences')
    check(e('tasksView.activeSection.collapsed&&!tasksView.completedSection.collapsed'),'manual Active and Completed disclosures survive reload')
    e('tasksView.activeToggle.click();tasksView.completedToggle.click()');reload()
    check(e('!tasksView.activeSection.collapsed&&tasksView.completedSection.collapsed'),'opposite manual group states also survive reload')
    check(e('!JSON.parse(localStorage.getItem("galaxy:user-data")).sidebarPaneRatio'),'split preference stays outside Universe data')
    for invalid in [99,-10,'broken']:
        e(f'persistence.preferences.update({{sidebarPaneRatio:{q(invalid)}}})');reload()
        check(e('sidebarPaneSplit.current.top>=sidebarPaneSplit.current.min&&sidebarPaneSplit.current.top<=sidebarPaneSplit.current.max'),'saved invalid/out-of-range split clamps safely: '+str(invalid))
    cdp.call('Emulation.setDeviceMetricsOverride',width=1100,height=440,deviceScaleFactor=1,mobile=False);e(frame)
    check(e('sidebarPaneSplit.current.top>=sidebarPaneSplit.current.min&&sidebarPaneSplit.current.top<=sidebarPaneSplit.current.max'),'shorter desktop viewport clamps layout safely')
    check(rect('#sidebar-utilities')['bottom']<=440,'utilities stay accessible on short desktop')
    cdp.call('Emulation.setDeviceMetricsOverride',width=1440,height=1000,deviceScaleFactor=1,mobile=False);e(frame)
    e('sidebarPaneSplit.handle.dispatchEvent(new MouseEvent("dblclick",{bubbles:true}));hierarchySidebar.setCollapsed(false)');e(frame)
    check(e('sidebarPaneSplit.ratio===null&&persistence.preferences.load().sidebarPaneRatio===null'),'double click resets to content-aware default')
    e(f'tasksView.rows.get({q(task_list)}).expand.click();sidebarPaneSplit.adjust(400)');e(frame)
    check(e('hierarchySidebar.tree.scrollHeight>hierarchySidebar.tree.clientHeight'),'overflowing Universe scrolls within its allocated pane')
    check(e('sidebarPaneSplit.secondary.scrollHeight>sidebarPaneSplit.secondary.clientHeight'),'overflowing Tasks scroll within secondary pane')
    check(e('["tasks-view","tasks-active","constellation-list"].every(id=>!["auto","scroll"].includes(getComputedStyle(document.getElementById(id)).overflowY))'),'no nested Tasks or Constellation scrollers on desktop')
    splitter_y=rect('#sidebar-pane-splitter')['y']
    e('hierarchySidebar.tree.scrollTop=80;sidebarPaneSplit.secondary.scrollTop=80');e(frame)
    check(rect('#sidebar-pane-splitter')['y']==splitter_y,'splitter stays stationary while both panes scroll')
    check(e('!sidebarPaneSplit.secondary.contains(document.getElementById("sidebar-utilities"))'),'Help Backup Account remain pinned outside content panes')
    for width in [180,260,360]:
        e(f'hierarchySidebar.setWidth({width})');e(frame)
        check(e('sidebarPaneSplit.secondary.scrollWidth<=sidebarPaneSplit.secondary.clientWidth&&sidebarPaneSplit.panes.scrollWidth<=sidebarPaneSplit.panes.clientWidth'),'narrow/wide sidebar has no horizontal overflow: '+str(width))
        r=rect(listrow+' .tasks-list-name');s=rect(listrow+' .tasks-summary')
        check(r['x']+r['width']<=s['x'],'long list label leaves progress count separate: '+str(width))
    e('hierarchySidebar.tree.scrollTop=0;sidebarPaneSplit.secondary.scrollTop=0');e(frame)
    shot('sidebar-refinement-desktop')
    e(f'tasksView.rows.get({q(task_list)}).expand.click()');e(frame)
    shot('sidebar-refinement-desktop-overview')
    e(f'tasksView.rows.get({q(task_list)}).expand.click()');e(frame)
    e('hierarchySidebar.universeSection.setCollapsed(true)');e(frame)
    check(e('sidebarPaneSplit.handle.hidden&&sidebarPaneSplit.secondary.clientHeight>100'),'collapsed Universe yields usable secondary content without divider')
    e('hierarchySidebar.universeSection.setCollapsed(false)');e(frame)
    cdp.call('Emulation.setTouchEmulationEnabled',enabled=True,maxTouchPoints=5)
    for width in [360,390,430]:
        cdp.call('Emulation.setDeviceMetricsOverride',width=width,height=844,deviceScaleFactor=1,mobile=True)
        e('hierarchySidebar.setCollapsed(false)');e(frame)
        check(e('sidebarPaneSplit.handle.hidden&&sidebarPaneSplit.handle.tabIndex===-1&&getComputedStyle(sidebarPaneSplit.panes).display==="contents"'),'mobile retains existing drawer flow with no splitter: '+str(width))
        check(rect(taskrow+' .task-view-check')['height']==44,'mobile task touch target stays 44px: '+str(width))
        check(abs(rect(taskrow+' .tasks-task-name')['x']-rect(universe_child+' .tree-name')['x']-9)<1,'mobile child indentation follows shared subgroup staircase: '+str(width))
        check(e('getComputedStyle(sidebarPaneSplit.secondary).maxHeight!=="none"'),'mobile scroll sizing remains unchanged: '+str(width))
        check(e('sidebarPaneSplit.secondary.scrollWidth<=sidebarPaneSplit.secondary.clientWidth'),'mobile Tasks has no horizontal overflow: '+str(width))
        hierarchy_alignment(str(width),9)
        e('hierarchySidebar.tree.scrollTop=0;sidebarPaneSplit.secondary.scrollTop=0');e(frame)
        shot('sidebar-refinement-mobile-'+str(width))
    check(not cdp.errors,'no uncaught browser errors during sidebar refinement checks')
